/// <summary>
/// The <c>AVAWHSProcessGuideCreateLPController</c> class is the controller class to run the create license Plate process
/// </summary>
[
    WHSWorkExecuteModeAttribute(WHSWorkExecuteMode::AVACreateLP)
]
class AVAWHSProcessGuideCreateLPController extends ProcessGuideController
{
    private static AVAProcessGuideBackEnabledNavigationAgentFactory navigationFactory  = new AVAProcessGuideBackEnabledNavigationAgentFactory();

}

Method.Source:
protected final ProcessGuideNavigationRoute initializeNavigationRoute()
{
    var navigationRoute = new ProcessGuideNavigationRouteReversible();

    navigationRoute.addFollowingStep(classStr(AVAWHSProcessGuidePromptContainerTypeStep), classStr(AVAWHSProcessGuidePromptLicensePlateIdStep));
    navigationRoute.addFollowingStep(classStr(AVAWHSProcessGuidePromptLicensePlateIdStep), classStr(AVAWHSProcessGuideDoCreateLicensePlaterStep));
    navigationRoute.addFollowingStep(classStr(AVAWHSProcessGuideDoCreateLicensePlaterStep), classStr(AVAWHSProcessGuidePromptContainerTypeStep));

    return navigationRoute;
}
